import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def make(last, first, section, email):
    return Student("1", last, first, section, email)


class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows([
            make("Young", "Zed", "A", "z@x.org"),
            make("Adams", "Amy", "B", "a@x.org")
        ])
        self.assertTrue(rows[0].startswith("Adams, Amy"))
        self.assertTrue(rows[1].startswith("Young, Zed"))

    def test_columns_line_up(self):
        rows = contact_rows([
            make("Adams", "Amy", "B", "a@x.org"),
            make("Longname", "Bartholomew", "C", "b@x.org")
        ])
        first = rows[0].index("B")
        self.assertEqual(rows[1].index("C"), first)
        self.assertEqual(
            rows[0].index("a@x"), rows[1].index("b@x")
        )

    def test_row_has_name_section_email(self):
        amy = make("Adams", "Amy", "B", "a@x.org")
        rows = contact_rows([amy])
        self.assertEqual(rows, ["Adams, Amy  B  a@x.org"])

    def test_missing_email_names_the_student(self):
        with self.assertRaises(ProjectError) as caught:
            contact_rows([
                make("Adams", "Amy", "B", "a@x.org"),
                make("Brown", "Bo", "B", None)
            ])
        self.assertIn("Brown, Bo", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([make("Brown", "Bo", "B", "  ")])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
